import{_ as t,o as n,c as a,a2 as o}from"./chunks/framework.OWFDNrRT.js";const p=JSON.parse('{"title":"SPEC-002: Native Menu Button Injection","description":"","frontmatter":{},"headers":[],"relativePath":"specs/SPEC-002-native-menu-injector.md","filePath":"specs/SPEC-002-native-menu-injector.md","lastUpdated":1774507673000}'),i={name:"specs/SPEC-002-native-menu-injector.md"};function s(d,e,r,c,l,h){return n(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="spec-002-native-menu-button-injection" tabindex="-1">SPEC-002: Native Menu Button Injection <a class="header-anchor" href="#spec-002-native-menu-button-injection" aria-label="Permalink to &quot;SPEC-002: Native Menu Button Injection&quot;">​</a></h1><p><strong>Status</strong>: Accepted <strong>Date</strong>: 2026-03-24 <strong>Author</strong>: DINOForge Agents <strong>Related ADR</strong>: <a href="./../adr/ADR-002-native-menu-injector">ADR-002: Native Menu Injector Design</a></p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><code>NativeMenuInjector</code> locates DINO&#39;s in-game UGUI main menu at runtime and injects a &quot;Mods&quot; button as a sibling of the native &quot;Settings&quot; button. When clicked, the button toggles the <code>ModMenuOverlay</code> (F10 menu) without requiring the player to know the keyboard shortcut.</p><p>The injector is a <code>MonoBehaviour</code> attached to the <code>DINOForge_Root</code> persistent <code>GameObject</code>. It is self-healing: it detects when the injected button has been destroyed (e.g., on scene unload) and re-injects automatically on the next scan cycle.</p><hr><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><h3 id="functional" tabindex="-1">Functional <a class="header-anchor" href="#functional" aria-label="Permalink to &quot;Functional&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Requirement</th></tr></thead><tbody><tr><td>F-01</td><td>A &quot;Mods&quot; button shall appear in DINO&#39;s main menu within 5 seconds of the menu becoming visible.</td></tr><tr><td>F-02</td><td>Clicking the &quot;Mods&quot; button shall toggle the <code>ModMenuOverlay</code> to visible/hidden.</td></tr><tr><td>F-03</td><td>The &quot;Mods&quot; button shall be visually identical in style (font, colours, hover/pressed states) to the native &quot;Settings&quot; button.</td></tr><tr><td>F-04</td><td>The injector shall be idempotent: injecting into a canvas that already contains a <code>DINOForge_ModsButton</code> shall reuse the existing button, not create a second one.</td></tr><tr><td>F-05</td><td>On scene change, the injector shall reset its injection state and attempt re-injection into the new scene&#39;s canvas.</td></tr><tr><td>F-06</td><td>If no suitable canvas or button is found, the injector shall log a diagnostic message and retry without throwing an exception to the caller.</td></tr><tr><td>F-07</td><td>A <code>static Action? OnScanNeeded</code> delegate shall be exposed to allow external code (e.g., tests, <code>RuntimeDriver</code>) to trigger a re-scan from the main thread.</td></tr></tbody></table><h3 id="non-functional" tabindex="-1">Non-Functional <a class="header-anchor" href="#non-functional" aria-label="Permalink to &quot;Non-Functional&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Requirement</th></tr></thead><tbody><tr><td>N-01</td><td>All <code>Resources.FindObjectsOfTypeAll&amp;lt;Canvas&amp;gt;()</code> calls shall execute only on the Unity main thread.</td></tr><tr><td>N-02</td><td>The injector shall never throw an unhandled exception. All injection paths are wrapped in <code>try/catch</code>.</td></tr><tr><td>N-03</td><td>The periodic re-scan interval shall be no less than 1 second to limit per-frame GC allocation.</td></tr><tr><td>N-04</td><td>The injected button shall not acquire EventSystem keyboard/gamepad focus automatically.</td></tr><tr><td>N-05</td><td>Click debounce shall prevent the menu from toggling more than once per 200 ms.</td></tr></tbody></table><hr><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Plugin.Awake()</span></span>
<span class="line"><span>  └─ PersistentRoot.AddComponent&lt;NativeMenuInjector&gt;()</span></span>
<span class="line"><span>       └─ RuntimeDriver.Initialize()</span></span>
<span class="line"><span>            ├─ injector.SetLogger(log)</span></span>
<span class="line"><span>            ├─ injector.SetModMenuHost(modMenuOverlay)</span></span>
<span class="line"><span>            └─ NativeMenuInjector.OnScanNeeded = () =&gt; injector.TryInjectMenuButton()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>NativeMenuInjector (MonoBehaviour on DINOForge_Root)</span></span>
<span class="line"><span>  ├─ Awake()  ──► SceneManager.activeSceneChanged += OnActiveSceneChanged</span></span>
<span class="line"><span>  ├─ Start()  ──► TryInjectMenuButton()</span></span>
<span class="line"><span>  ├─ Update() ──► every 2s: TryInjectMenuButton()   [if not injected]</span></span>
<span class="line"><span>  │               on button destroy: reset _injected flag</span></span>
<span class="line"><span>  └─ OnDestroy() ──► SceneManager.activeSceneChanged -= OnActiveSceneChanged</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TryInjectMenuButton()</span></span>
<span class="line"><span>  ├─ Resources.FindObjectsOfTypeAll&lt;Canvas&gt;()</span></span>
<span class="line"><span>  ├─ foreach active canvas:</span></span>
<span class="line"><span>  │    └─ FindSettingsButton(canvas)</span></span>
<span class="line"><span>  │         ├─ NativeUiHelper.FindButtonByText(canvas.transform, &quot;Settings&quot;)</span></span>
<span class="line"><span>  │         └─ NativeUiHelper.FindButtonByText(canvas.transform, &quot;Options&quot;)</span></span>
<span class="line"><span>  └─ InjectButton(settingsButton)</span></span>
<span class="line"><span>       ├─ Duplicate-guard scan (DINOForge_ModsButton prefix)</span></span>
<span class="line"><span>       ├─ NativeUiHelper.CloneButton(settingsButton, &quot;Mods&quot;)</span></span>
<span class="line"><span>       ├─ SyncButtonVisualStyle(modsButton, settingsButton)</span></span>
<span class="line"><span>       ├─ NativeUiHelper.PositionAfterSibling(modsRect, settingsRect)</span></span>
<span class="line"><span>       ├─ modsButton.SetActive(true); modsButton.interactable = true</span></span>
<span class="line"><span>       ├─ Raycast target validation + GraphicRaycaster check</span></span>
<span class="line"><span>       ├─ RewireModsButtonClick(modsButton)   // clears inherited listeners</span></span>
<span class="line"><span>       ├─ Navigation.Mode = None              // isolate from native nav graph</span></span>
<span class="line"><span>       └─ _injectedButton = modsButton; _injected = true</span></span></code></pre></div><hr><h2 id="implementation-details" tabindex="-1">Implementation Details <a class="header-anchor" href="#implementation-details" aria-label="Permalink to &quot;Implementation Details&quot;">​</a></h2><h3 id="finding-the-dino-main-menu" tabindex="-1">Finding the DINO Main Menu <a class="header-anchor" href="#finding-the-dino-main-menu" aria-label="Permalink to &quot;Finding the DINO Main Menu&quot;">​</a></h3><p>DINO does not expose a stable API surface for its menus. The injector uses a canvas-agnostic strategy:</p><ol><li>Call <code>Resources.FindObjectsOfTypeAll&amp;lt;Canvas&amp;gt;()</code> to enumerate every loaded <code>Canvas</code> object, including inactive ones.</li><li>Filter to canvases where <code>canvas.gameObject.activeInHierarchy == true</code>.</li><li>For each active canvas, search for a button whose <code>UnityEngine.UI.Text</code> child contains the text &quot;Settings&quot; (primary) or &quot;Options&quot; (fallback).</li><li>The first canvas that yields a matching button is used as the injection target.</li></ol><p>Canvas names are logged for diagnostics but are not used as a filter criterion. The assumption that a &quot;Settings&quot; or &quot;Options&quot; labelled button exists in the main menu has been validated against DINO v1.4.x and is expected to remain stable.</p><h3 id="finding-the-correct-button-container" tabindex="-1">Finding the Correct Button Container <a class="header-anchor" href="#finding-the-correct-button-container" aria-label="Permalink to &quot;Finding the Correct Button Container&quot;">​</a></h3><p>The injected &quot;Mods&quot; button is placed as a sibling of the &quot;Settings&quot; button, within the same parent <code>Transform</code>. This preserves the vertical stack layout used by DINO&#39;s menu (typically a <code>VerticalLayoutGroup</code>). The sibling index is set to immediately follow the Settings button via <code>NativeUiHelper.PositionAfterSibling(modsRect, settingsRect)</code>.</p><h3 id="injecting-the-mods-button" tabindex="-1">Injecting the &quot;Mods&quot; Button <a class="header-anchor" href="#injecting-the-mods-button" aria-label="Permalink to &quot;Injecting the &quot;Mods&quot; Button&quot;">​</a></h3><p>Injection proceeds in eight logged steps:</p><table tabindex="0"><thead><tr><th>Step</th><th>Action</th></tr></thead><tbody><tr><td>1</td><td><code>NativeUiHelper.CloneButton(settingsButton, &quot;Mods&quot;)</code> — <code>Object.Instantiate</code> + rename</td></tr><tr><td>2</td><td><code>NativeUiHelper.PositionAfterSibling</code> — sets sibling index after Settings</td></tr><tr><td>3</td><td><code>modsButton.gameObject.SetActive(true)</code> + <code>interactable = true</code></td></tr><tr><td>4</td><td><code>CanvasGroup</code> check — enables <code>interactable</code> and <code>blocksRaycasts</code> if present</td></tr><tr><td>5</td><td>Raycast diagnostics — verifies <code>targetGraphic.raycastTarget</code>, parent <code>CanvasGroup</code> chain, and <code>GraphicRaycaster</code> on the canvas</td></tr><tr><td>6</td><td><code>RewireModsButtonClick</code> — replaces all <code>onClick</code> listeners with <code>OnModsButtonClicked</code></td></tr><tr><td>7</td><td><code>Navigation.Mode = None</code> — isolates button from EventSystem navigation graph</td></tr><tr><td>8</td><td>Final state verification — logs all critical fields before setting <code>_injected = true</code></td></tr></tbody></table><p>If any step throws, the exception is caught and logged as a warning. <code>_injected</code> is not set to <code>true</code> and the injector will retry on the next scan cycle.</p><h3 id="onscanneeded-delegate" tabindex="-1"><code>OnScanNeeded</code> Delegate <a class="header-anchor" href="#onscanneeded-delegate" aria-label="Permalink to &quot;\`OnScanNeeded\` Delegate&quot;">​</a></h3><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> static</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> System</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">? </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">OnScanNeeded</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>This static delegate is set by <code>RuntimeDriver</code> after the injector is created:</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NativeMenuInjector.OnScanNeeded </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> injector.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">TryInjectMenuButton</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>It allows any main-thread caller — including tests, <code>RuntimeDriver.Update()</code>, or future tooling — to request an immediate scan without coupling directly to the <code>NativeMenuInjector</code> instance. The delegate is <code>null</code>-safe: callers must check before invoking.</p><h3 id="retry-logic" tabindex="-1">Retry Logic <a class="header-anchor" href="#retry-logic" aria-label="Permalink to &quot;Retry Logic&quot;">​</a></h3><p>Retry is automatic and uses two complementary mechanisms:</p><ol><li><strong>Scene change trigger</strong>: <code>OnActiveSceneChanged</code> resets <code>_injected = false</code>, clears <code>_injectedButton</code>, and calls <code>TryInjectMenuButton()</code> immediately.</li><li><strong><code>Update()</code> timer</strong>: every <code>RescanInterval</code> (2 seconds), if <code>_injected</code> is false or <code>_injectedButton</code> has been destroyed, <code>TryInjectMenuButton()</code> is called again.</li></ol><p>There is no maximum retry count. The injector keeps trying indefinitely because:</p><ul><li>DINO&#39;s boot takes 60–90 seconds and the menu may not appear until the player clicks through the splash screen.</li><li>Scene transitions can reload the menu at any time during a play session.</li></ul><h3 id="initialgameloader-click-through-requirement" tabindex="-1"><code>InitialGameLoader</code> Click-Through Requirement <a class="header-anchor" href="#initialgameloader-click-through-requirement" aria-label="Permalink to &quot;\`InitialGameLoader\` Click-Through Requirement&quot;">​</a></h3><p>DINO presents a loading/splash screen (<code>InitialGameLoader</code>) immediately after launch. The main menu <code>Canvas</code> is not instantiated until the player manually clicks through this screen. This is a game-side design constraint with no programmatic bypass available without patching DINO internals.</p><p>Consequence: the injector will log &quot;0 Settings buttons found&quot; for every scan attempt during the 60–90 second boot window. This is expected behaviour, not an error. The player must advance past the splash screen manually before the Mods button appears.</p><h3 id="visual-style-synchronisation" tabindex="-1">Visual Style Synchronisation <a class="header-anchor" href="#visual-style-synchronisation" aria-label="Permalink to &quot;Visual Style Synchronisation&quot;">​</a></h3><p><code>SyncButtonVisualStyle(Button target, Button source)</code> copies the following properties from the Settings button to the Mods button:</p><ul><li><code>Button.transition</code> (ColorTint / SpriteSwap / Animation)</li><li><code>Button.colors</code> (color block: normal, highlighted, pressed, disabled, fade duration)</li><li><code>Button.spriteState</code> (highlighted, pressed, selected, disabled sprites)</li><li><code>Button.animationTriggers</code> (animator trigger names)</li><li><code>Button.targetGraphic</code> (resolved by relative path from button root to graphic transform)</li><li><code>UnityEngine.UI.Text</code>: <code>font</code>, <code>fontStyle</code>, <code>fontSize</code>, <code>color</code>, <code>alignment</code>, <code>material</code></li></ul><p>This ensures the Mods button matches the game&#39;s visual skin without requiring any bundled assets.</p><hr><h2 id="known-constraints" tabindex="-1">Known Constraints <a class="header-anchor" href="#known-constraints" aria-label="Permalink to &quot;Known Constraints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Constraint</th><th>Detail</th></tr></thead><tbody><tr><td>Main-thread only</td><td><code>Resources.FindObjectsOfTypeAll&amp;lt;Canvas&amp;gt;()</code> deadlocks if called from a background thread during asset loading. All scans must run on the Unity main thread.</td></tr><tr><td>Splash screen gate</td><td>Player must click through <code>InitialGameLoader</code> before the main menu is visible. Scans before this point return no results and retry silently.</td></tr><tr><td>UGUI dependency</td><td>Approach is specific to Unity UGUI. A future DINO migration to UI Toolkit would require a full rewrite of the injector.</td></tr><tr><td>No keyboard/gamepad auto-focus</td><td>The Mods button does not take EventSystem focus automatically to avoid interfering with DINO&#39;s native menu navigation.</td></tr><tr><td>Canvas name variability</td><td>Canvas names are not stable across DINO versions; the injector relies on button text instead, which is more stable but still DINO-version-dependent.</td></tr><tr><td>Persistent root required</td><td>The injector lives on <code>DINOForge_Root</code>. If that object is destroyed (e.g., resurrection fails), the injector is lost until the next resurrection cycle.</td></tr><tr><td><code>UnityEngine.UI.Text</code> only</td><td>The button text scanner uses the legacy <code>UnityEngine.UI.Text</code> component. If DINO switches to <code>TextMeshPro</code>, <code>FindButtonByText</code> will need to be updated.</td></tr></tbody></table><hr><h2 id="test-plan" tabindex="-1">Test Plan <a class="header-anchor" href="#test-plan" aria-label="Permalink to &quot;Test Plan&quot;">​</a></h2><h3 id="unit-tests" tabindex="-1">Unit Tests <a class="header-anchor" href="#unit-tests" aria-label="Permalink to &quot;Unit Tests&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Test</th><th>Description</th></tr></thead><tbody><tr><td><code>TryInjectMenuButton_NoCanvases_DoesNotThrow</code></td><td>Call with no canvases present; verify no exception and <code>_injected == false</code>.</td></tr><tr><td><code>TryInjectMenuButton_ActiveCanvasNoSettingsButton_DoesNotThrow</code></td><td>Active canvas with no Settings/Options button; verify retry state.</td></tr><tr><td><code>TryInjectMenuButton_FindsSettingsButton_SetsInjected</code></td><td>Provide a mock canvas with a Settings button; verify <code>_injected == true</code> after call.</td></tr><tr><td><code>InjectButton_DuplicateGuard_DoesNotDoubleInject</code></td><td>Call inject twice with same parent; verify only one <code>DINOForge_ModsButton</code> child exists.</td></tr><tr><td><code>RewireModsButtonClick_ClearsInheritedListeners</code></td><td>Verify that the cloned button&#39;s original listeners are replaced, not appended to.</td></tr><tr><td><code>SyncButtonVisualStyle_CopiesColorBlock</code></td><td>Verify color block matches source after sync.</td></tr><tr><td><code>OnModsButtonClicked_Debounce_SecondClickIgnored</code></td><td>Fire two clicks within 200 ms; verify <code>Toggle()</code> called exactly once.</td></tr><tr><td><code>OnModsButtonClicked_NullMenuHost_DoesNotThrow</code></td><td>Click with <code>_menuHost == null</code>; verify warning logged, no exception.</td></tr></tbody></table><h3 id="integration-tests" tabindex="-1">Integration Tests <a class="header-anchor" href="#integration-tests" aria-label="Permalink to &quot;Integration Tests&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Test</th><th>Description</th></tr></thead><tbody><tr><td><code>SceneChange_ResetsInjectionState</code></td><td>Simulate <code>OnActiveSceneChanged</code>; verify <code>_injected</code> reset and re-scan triggered.</td></tr><tr><td><code>Update_ButtonDestroyed_ResetsAndRescans</code></td><td>Destroy <code>_injectedButton</code> externally; advance timer; verify <code>_injected</code> reset and re-scan.</td></tr><tr><td><code>OnScanNeeded_TriggersInjection</code></td><td>Set <code>OnScanNeeded</code>, invoke it, verify <code>TryInjectMenuButton</code> is called.</td></tr><tr><td><code>FullBoot_InjectionSucceeds</code></td><td>End-to-end test with a mock DINO main menu canvas; verify Mods button present and clickable.</td></tr></tbody></table><h3 id="manual-acceptance-criteria" tabindex="-1">Manual Acceptance Criteria <a class="header-anchor" href="#manual-acceptance-criteria" aria-label="Permalink to &quot;Manual Acceptance Criteria&quot;">​</a></h3><ol><li>Launch DINO with DINOForge installed.</li><li>Wait for the splash screen; click through <code>InitialGameLoader</code>.</li><li>Main menu appears; &quot;Mods&quot; button is visible adjacent to &quot;Settings&quot;.</li><li>&quot;Mods&quot; button has identical visual style to &quot;Settings&quot;.</li><li>Clicking &quot;Mods&quot; opens the DINOForge mod menu overlay.</li><li>Clicking &quot;Mods&quot; again closes the overlay.</li><li>Start a game, pause; verify &quot;Mods&quot; button appears in the pause menu.</li><li>Return to main menu; verify &quot;Mods&quot; button persists after scene transition.</li></ol><hr><h2 id="open-issues" tabindex="-1">Open Issues <a class="header-anchor" href="#open-issues" aria-label="Permalink to &quot;Open Issues&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Issue</th><th>Priority</th></tr></thead><tbody><tr><td>OI-01</td><td><code>InitialGameLoader</code> has no programmatic skip path. Players on slow machines may wait 90+ seconds before the Mods button appears. A future option: hook <code>InitialGameLoader.OnDestroy</code> to trigger an immediate scan.</td><td>Low</td></tr><tr><td>OI-02</td><td>If DINO uses <code>TextMeshPro</code> for button labels in a future update, <code>NativeUiHelper.FindButtonByText</code> will need a <code>TMP_Text</code> fallback.</td><td>Medium</td></tr><tr><td>OI-03</td><td><code>Navigation.Mode.None</code> on the Mods button means it is unreachable via gamepad/keyboard navigation. A future enhancement could wire explicit <code>selectOnUp</code>/<code>selectOnDown</code> links to adjacent buttons.</td><td>Low</td></tr><tr><td>OI-04</td><td>The 2-second rescan timer fires even during active gameplay (when the menu is not visible), causing minor unnecessary scans. A scene-name or canvas-visibility pre-check could eliminate these.</td><td>Low</td></tr></tbody></table><hr><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p><strong>Implementation</strong>: Complete (<code>src/Runtime/UI/NativeMenuInjector.cs</code>) <strong>Tests</strong>: Partial (manual acceptance passing; automated unit/integration tests pending) <strong>Documentation</strong>: This specification + ADR-002</p>`,61)])])}const g=t(i,[["render",s]]);export{p as __pageData,g as default};
